suspend fun <T> withRetry(
    maxAttempts: Int = 3,
    initialDelay: Duration = 100.milliseconds,
    factor: Double = 2.0,
    op: suspend () -> T
): T {
    var attempt = 0
    var delay = initialDelay
    while (true) {
        try {
            return op()
        } catch (e: TransientException) {
            attempt++
            if (attempt >= maxAttempts) throw e
            delay(delay + jitter(delay))
            delay = delay * factor
        }
    }
}

